import zipfile
import re
import os

# Extract and verify content
extract_dir = '/tmp/final_verify'
os.makedirs(extract_dir, exist_ok=True)

with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx', 'r') as zf:
    zf.extractall(extract_dir)

print("=== Final Verification ===\n")

# Read all XML files
for root, dirs, files in os.walk(extract_dir):
    for fn in files:
        if fn.endswith('.xml') or fn.endswith('.hpf'):
            path = os.path.join(root, fn)
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()

            print(f"\n--- {fn} ---")

            # Check for placeholders
            placeholders = re.findall(r'\{\{[^}]+\}\}', content)
            if placeholders:
                print(f"❌ Remaining placeholders: {placeholders}")
            else:
                print("✅ No remaining placeholders")

            # Extract key text content
            for line in content.split('\n'):
                if '<hp:t>' in line:
                    # Extract text between <hp:t> tags
                    texts = re.findall(r'<hp:t>([^<]*)</hp:t>', line)
                    for t in texts:
                        if t.strip():
                            print(f"  Content: {t}")

print("\n=== Verification Summary ===")

# Check output file exists
if os.path.exists('/root/safety_audit_brief_final.hwpx'):
    size = os.path.getsize('/root/safety_audit_brief_final.hwpx')
    print(f"✅ Output file exists: /root/safety_audit_brief_final.hwpx ({size} bytes)")
else:
    print("❌ Output file not found")
